import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Rajdhani:wght@400;500;600;700&display=swap');\n*{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --bg:#0a0c0f;--bg2:#0d1117;--bg3:#111820;\n  --panel:#131a22;--panel2:#1a2332;\n  --b:#1e3a5f;--b2:#0f2540;\n  --g:#00ff88;--g2:#00cc6a;\n  --c:#00d4ff;--y:#ffd700;--o:#ff8c00;\n  --r:#ff3b3b;--p:#9d4edd;--bl:#2979ff;\n  --t:#c8d8e8;--t2:#7a9bb5;--t3:#4a6a85;\n  --mono:'JetBrains Mono',monospace;\n  --sans:'Rajdhani','Segoe UI',sans-serif;\n}\nbody{background:var(--bg);color:var(--t);font-family:var(--mono);font-size:13px;line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.012) 2px,rgba(0,255,136,.012) 4px);pointer-events:none;z-index:9999}\n.wrap{max-width:1100px;margin:0 auto;padding:20px 16px}\n/* panel */\n.panel{background:var(--panel);border:1px solid var(--b2);margin-bottom:14px;overflow:hidden}\n.ph{background:var(--panel2);border-bottom:1px solid var(--b);padding:8px 16px;display:flex;align-items:center;gap:10px}\n.pi{font-size:14px}\n.pt{font-family:var(--sans);font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--c)}\n.pn{margin-left:auto;font-size:10px;color:var(--t3);letter-spacing:1px}\n.pb{padding:18px 20px}\n/* header */\n.hdr{background:linear-gradient(135deg,#0d1a2e,#0a1520);border:1px solid var(--b);border-top:3px solid var(--g);padding:20px 24px;margin-bottom:16px;position:relative;overflow:hidden}\n.hdr::after{content:'';position:absolute;right:-60px;top:-60px;width:200px;height:200px;background:radial-gradient(circle,rgba(0,255,136,.05),transparent 70%);pointer-events:none}\n@keyframes pulse{0%,100%{box-shadow:0 0 6px var(--g)}50%{box-shadow:0 0 16px var(--g);opacity:.5}}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}\n/* tabs */\n.tabs{display:flex;gap:0;border-bottom:1px solid var(--b2);margin-bottom:16px;overflow-x:auto}\n.tab{padding:8px 16px;font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;color:var(--t3);cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap;transition:all .2s}\n.tab.active{color:var(--g);border-bottom-color:var(--g)}\n.tab:hover:not(.active){color:var(--t2)}\n.tab-content{display:none}.tab-content.active{display:block}\n/* concept blocks */\n.cb{background:var(--bg3);border:1px solid var(--b2);padding:14px;border-left:3px solid var(--c)}\n.cb.g{border-left-color:var(--g)}.cb.y{border-left-color:var(--y)}.cb.p{border-left-color:var(--p)}.cb.o{border-left-color:var(--o)}.cb.r{border-left-color:var(--r)}\n.cbt{font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;color:var(--c)}\n.cb.g .cbt{color:var(--g)}.cb.y .cbt{color:var(--y)}.cb.p .cbt{color:var(--p)}.cb.o .cbt{color:var(--o)}.cb.r .cbt{color:var(--r)}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n/* terminal */\n.term{background:#050810;border:1px solid #1a2d45;overflow:hidden}\n.tbar{background:#0d1520;border-bottom:1px solid #1a2d45;padding:7px 14px;display:flex;align-items:center;gap:8px}\n.td{width:10px;height:10px;border-radius:50%}\n.tbody{padding:14px 18px;font-size:12px;line-height:1.8}\n.pr{color:var(--g)}.cmd{color:#fff}.sec{display:block;color:var(--t3);font-size:10px;letter-spacing:2px;text-transform:uppercase;border-top:1px solid #1a2d45;padding-top:10px;margin:10px 0 4px}\n.out{display:block;color:var(--t2)}.ocn{display:block;color:var(--c)}.oyn{display:block;color:var(--y)}.orn{display:block;color:var(--o)}.ogn{display:block;color:var(--g)}\n/* process tree */\n.ptree{background:var(--bg);border:1px solid var(--b2);padding:16px 20px;font-size:12px;line-height:2}\n/* info/warn */\n.info{display:flex;gap:8px;padding:8px 12px;background:rgba(0,212,255,.06);border-left:3px solid var(--c);margin:10px 0;font-size:12px;color:var(--t2)}\n.warn{display:flex;gap:8px;padding:8px 12px;background:rgba(255,215,0,.06);border-left:3px solid var(--y);margin:10px 0;font-size:12px;color:var(--t2)}\n.ic{color:var(--c);flex-shrink:0}.wc{color:var(--y);flex-shrink:0}\n/* memory diagram */\n.mem-map{background:var(--bg);border:1px solid var(--b2);padding:16px}\n.mem-row{display:flex;align-items:stretch;margin-bottom:2px}\n.mem-addr{width:110px;min-width:110px;font-size:10px;color:var(--t3);display:flex;align-items:center;justify-content:flex-end;padding-right:10px;font-family:var(--mono)}\n.mem-seg{flex:1;padding:7px 12px;text-align:center}\n.mem-seg-name{font-family:var(--sans);font-size:12px;font-weight:600}\n.mem-seg-desc{font-size:10px;color:var(--t3);margin-top:2px}\n.ms-kernel{background:rgba(255,215,0,.08);border:1px solid rgba(255,215,0,.3)}\n.ms-stack {background:rgba(255,140,0,.08);border:1px solid rgba(255,140,0,.3)}\n.ms-heap  {background:rgba(0,212,255,.07);border:1px solid rgba(0,212,255,.3)}\n.ms-data  {background:rgba(157,78,221,.08);border:1px solid rgba(157,78,221,.3)}\n.ms-text  {background:rgba(0,255,136,.07);border:1px solid rgba(0,255,136,.3)}\n.ms-null  {background:rgba(255,59,59,.06);border:1px solid rgba(255,59,59,.3)}\n.ms-gap   {background:rgba(255,255,255,.02);border:1px dashed var(--b2)}\n/* scheduler viz */\n.sched-track{background:var(--bg);border:1px solid var(--b2);padding:14px}\n.sched-row{display:flex;align-items:center;gap:8px;margin-bottom:8px}\n.sched-label{width:80px;min-width:80px;font-size:11px;color:var(--t3);font-family:var(--sans);font-weight:600;text-transform:uppercase;letter-spacing:1px}\n.sched-bar-wrap{flex:1;background:rgba(255,255,255,.04);height:26px;display:flex;overflow:hidden}\n.sched-slot{height:100%;display:flex;align-items:center;justify-content:center;font-size:9px;font-family:var(--sans);font-weight:700;letter-spacing:.5px;transition:all .3s}\n/* boot steps */\n.boot-step{display:flex;gap:14px;align-items:flex-start;position:relative;margin-bottom:0}\n.boot-line{position:absolute;left:15px;top:32px;bottom:-10px;width:1px;background:linear-gradient(to bottom,var(--g),transparent)}\n.boot-dot{width:32px;min-width:32px;height:32px;border-radius:50%;border:2px solid var(--g);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--g);background:rgba(0,255,136,.08);flex-shrink:0;font-family:var(--sans)}\n.boot-body{flex:1;background:var(--bg3);border:1px solid var(--b2);padding:10px 14px;margin-bottom:10px}\n.boot-title{font-family:var(--sans);font-weight:600;font-size:13px;color:var(--g);margin-bottom:3px}\n.boot-desc{font-size:11.5px;color:var(--t2)}\n.boot-cmd{margin-top:6px;background:var(--bg);padding:4px 10px;font-size:11px;color:var(--c);border-left:2px solid var(--c)}\n/* syscall table */\n.stbl{width:100%;border-collapse:collapse;font-size:12px}\n.stbl th{background:var(--panel2);padding:9px 12px;text-align:left;font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;border-bottom:2px solid var(--b);color:var(--c)}\n.stbl td{padding:8px 12px;border-bottom:1px solid var(--b2);color:var(--t2);vertical-align:top}\n.stbl td:first-child{color:var(--g);font-size:11px}\n.stbl td:nth-child(2){color:var(--c)}\n.stbl tr:hover td{background:rgba(255,255,255,.02)}\n/* checklist */\n.cl{list-style:none}\n.cl li{padding:7px 0;border-bottom:1px solid var(--b2);font-size:12.5px;display:flex;align-items:flex-start;gap:10px;color:var(--t2)}\n.chk{width:16px;height:16px;min-width:16px;border:1px solid var(--g);background:rgba(0,255,136,.1);display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--g);margin-top:1px}\n.tag{padding:2px 8px;border-radius:2px;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;font-family:var(--sans);margin-left:auto;flex-shrink:0}\n.tg{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.3)}\n.tc{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.3)}\n.ty{background:rgba(255,215,0,.1);color:var(--y);border:1px solid rgba(255,215,0,.3)}\n.tp{background:rgba(157,78,221,.12);color:var(--p);border:1px solid rgba(157,78,221,.3)}\n.to{background:rgba(255,140,0,.1);color:var(--o);border:1px solid rgba(255,140,0,.3)}\n/* divider */\n.div{height:1px;background:linear-gradient(to right,transparent,var(--b),transparent);margin:12px 0}\n/* ipc grid */\n.ipc-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.ipc-icon{font-size:20px;margin-bottom:6px}\n.ipc-name{font-family:var(--sans);font-weight:700;font-size:13px;color:var(--t);margin-bottom:4px}\n.ipc-desc{font-size:11px;color:var(--t3);line-height:1.5;margin-bottom:6px}\n.ipc-cmd{font-size:10px;color:var(--c);background:var(--bg);padding:3px 8px;border-left:2px solid var(--c)}\n/* hl */\n.hl{color:var(--g);font-weight:600}.hc{color:var(--c)}.hy{color:var(--y)}.ho{color:var(--o)}.hp{color:var(--p)}.hr{color:var(--r)}\n/* summary */\n.sum-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.sc-l{font-family:var(--sans);font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:600;color:var(--t3);margin-bottom:6px}\n.sc-v{font-size:12px;color:var(--t);line-height:1.6}\n.next{background:linear-gradient(135deg,rgba(0,255,136,.08),rgba(0,212,255,.05));border:1px solid rgba(0,255,136,.3);padding:14px 18px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}\n.ns-t{font-family:var(--sans);font-weight:600;font-size:14px;color:var(--g)}\n.ns-s{font-size:11px;color:var(--t3);margin-top:2px}\n.ns-b{background:var(--bg);border:1px solid var(--b);padding:6px 16px;font-size:12px;color:var(--g);cursor:pointer;font-family:var(--mono);transition:all .2s}\n.ns-b:hover{background:rgba(0,255,136,.1);border-color:var(--g)}\n/* interactive sched */\n.proc-state{display:inline-block;padding:2px 8px;font-size:10px;font-family:var(--sans);font-weight:700;letter-spacing:1px;text-transform:uppercase;border-radius:2px}\n.ps-run{background:rgba(0,255,136,.15);color:var(--g);border:1px solid rgba(0,255,136,.4)}\n.ps-wait{background:rgba(255,215,0,.12);color:var(--y);border:1px solid rgba(255,215,0,.4)}\n.ps-sleep{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.4)}\n.ps-zombie{background:rgba(255,59,59,.1);color:var(--r);border:1px solid rgba(255,59,59,.4)}\n.ps-stop{background:rgba(157,78,221,.1);color:var(--p);border:1px solid rgba(157,78,221,.4)}\n.proc-row{display:flex;align-items:center;gap:12px;padding:7px 0;border-bottom:1px solid var(--b2);font-size:12px}\n.proc-pid{width:50px;color:var(--t3);font-size:11px}\n.proc-name{width:120px;color:var(--t)}\n.proc-ppid{width:60px;color:var(--t3);font-size:11px}\n.proc-desc{flex:1;color:var(--t2);font-size:11px}";
const markup = "<div class=\"wrap\">\n\n<!-- ═══ HEADER ═══ -->\n<div class=\"hdr\">\n  <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <div style=\"width:8px;height:8px;border-radius:50%;background:var(--g);animation:pulse 2s infinite\"></div>\n        <span style=\"font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--g)\">STEP 02 / MODULE 1 ● ACTIVE</span>\n      </div>\n      <h1 style=\"font-family:var(--sans);font-size:26px;font-weight:700;color:#fff;letter-spacing:1px;line-height:1.2\">\n        Linux <span style=\"color:var(--g)\">Architecture</span> — Deep Dive\n      </h1>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:10px\">\n        <span class=\"tag tg\">● Intermediate</span>\n        <span class=\"tag tc\">⊞ Kernel Internals</span>\n        <span class=\"tag ty\">⊛ Process Management</span>\n        <span class=\"tag tp\">⬡ Memory Management</span>\n        <span class=\"tag to\">⊕ Boot + systemd</span>\n      </div>\n    </div>\n    <div style=\"text-align:right;font-size:11px;color:var(--t3);line-height:1.9;font-family:var(--mono)\">\n      <div>MODULE: <span style=\"color:var(--c)\">kernel-arch-02</span></div>\n      <div>DEPTH: <span style=\"color:var(--c)\">L5–L7</span></div>\n      <div>PANELS: <span style=\"color:var(--c)\">12</span></div>\n      <div>PREREQ: <span style=\"color:var(--c)\">Step 01 ✓</span></div>\n      <div style=\"margin-top:6px;font-size:10px;color:#1e6a3a\">▓▓▓▓▓▓▓▓░░ KERNEL LOADED</div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 01 — KERNEL ARCHITECTURE ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">⚙</span><span class=\"pt\">Kernel Architecture — Monolithic Deep Structure</span><span class=\"pn\">PANEL 01</span></div>\n  <div class=\"pb\">\n    <div class=\"grid2\">\n      <div class=\"cb g\">\n        <div class=\"cbt\">Monolithic Kernel — What It Really Means</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          <span class=\"hl\">All kernel subsystems run in a single address space</span> (Ring 0 / kernel space) as one large binary. Device drivers, filesystem code, network stack, memory manager, scheduler — all compiled together.<br><br>\n          Benefit: <span class=\"hl\">zero context-switch overhead</span> between subsystems. A VFS call to ext4 that triggers a block device driver that needs a DMA interrupt — all in kernel space, no IPC, no boundary crossings.<br><br>\n          Risk: a bug in any driver can <span class=\"hr\">kernel panic</span> the entire system. This is why driver quality matters critically on Linux.\n        </div>\n      </div>\n      <div class=\"cb y\">\n        <div class=\"cbt\">Kernel Space vs User Space</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          <span class=\"hy\">Kernel space</span> = Ring 0. Full CPU privilege. Direct hardware access. Unlimited memory access. One crash = system down.<br><br>\n          <span class=\"hl\">User space</span> = Ring 3. Restricted. Cannot access hardware directly. Cannot access other processes' memory. One crash = only that process dies.<br><br>\n          The boundary is enforced by the <span class=\"hc\">CPU's privilege rings</span>. Crossing it requires a <strong>system call</strong> — a controlled trap into the kernel.\n        </div>\n      </div>\n      <div class=\"cb\">\n        <div class=\"cbt\">CPU Privilege Rings</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.7\">\n          x86 defines 4 rings (0–3). Linux uses only 2:<br>\n          <span class=\"hy\">Ring 0</span> — Kernel. Can execute ANY instruction, access ANY memory.<br>\n          <span class=\"hl\">Ring 3</span> — User processes. Hardware-enforced sandbox.<br><br>\n          Rings 1 &amp; 2 exist but are unused in Linux. Some hypervisors exploit them for virtualisation boundaries.\n        </div>\n      </div>\n      <div class=\"cb p\">\n        <div class=\"cbt\">Kernel Modules (LKM)</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          Linux supports <span class=\"hp\">Loadable Kernel Modules</span> — code that can be dynamically inserted into the running kernel without rebooting.<br><br>\n          <span class=\"hc\">lsmod</span> — list loaded modules<br>\n          <span class=\"hc\">modprobe</span> — load a module with dependencies<br>\n          <span class=\"hc\">rmmod</span> — remove a module<br><br>\n          Device drivers (wifi, GPU, USB) are typically modules. This extends monolithic design without requiring recompilation.\n        </div>\n      </div>\n    </div>\n\n    <!-- Architecture visual -->\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:16px;margin-top:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:12px\">Kernel Internal Subsystem Map</div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:6px\">\n        <div style=\"background:rgba(255,215,0,.07);border:1px solid rgba(255,215,0,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">⚙</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--y)\">Scheduler (CFS)</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">CPU time distribution</div>\n        </div>\n        <div style=\"background:rgba(0,212,255,.07);border:1px solid rgba(0,212,255,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">◫</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--c)\">Memory Mgr</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">Virtual memory · paging · swap</div>\n        </div>\n        <div style=\"background:rgba(0,255,136,.07);border:1px solid rgba(0,255,136,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">📂</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--g)\">VFS Layer</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">Unified file abstraction</div>\n        </div>\n        <div style=\"background:rgba(255,140,0,.07);border:1px solid rgba(255,140,0,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">🌐</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--o)\">Network Stack</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">TCP/IP · sockets · netfilter</div>\n        </div>\n        <div style=\"background:rgba(157,78,221,.08);border:1px solid rgba(157,78,221,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">🔒</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--p)\">LSM Security</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">SELinux · AppArmor · capabilities</div>\n        </div>\n        <div style=\"background:rgba(41,121,255,.07);border:1px solid rgba(41,121,255,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">🔌</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:#5599ff\">Device Drivers</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">LKMs · block · char · net</div>\n        </div>\n        <div style=\"background:rgba(255,59,59,.06);border:1px solid rgba(255,59,59,.25);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">⚡</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--r)\">IPC</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">pipes · sockets · signals · SHM</div>\n        </div>\n        <div style=\"background:rgba(0,255,136,.05);border:1px solid rgba(0,255,136,.15);padding:10px;text-align:center\">\n          <div style=\"font-size:16px;margin-bottom:4px\">📞</div>\n          <div style=\"font-family:var(--sans);font-size:12px;font-weight:700;color:var(--g2)\">Syscall Interface</div>\n          <div style=\"font-size:10px;color:var(--t3);margin-top:3px\">User ↔ Kernel gateway</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 02 — SYSTEM CALLS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">📞</span><span class=\"pt\">System Calls — The User↔Kernel Gateway</span><span class=\"pn\">PANEL 02</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span class=\"ic\">ℹ</span><span>A <strong style=\"color:var(--c)\">system call (syscall)</strong> is the ONLY legitimate way for user-space code to request kernel services. The CPU executes a <code>syscall</code> instruction (x86-64), switches to Ring 0, jumps to the kernel's syscall dispatch table, executes the handler, then returns to Ring 3.</span></div>\n\n    <table class=\"stbl\" style=\"margin-bottom:14px\">\n      <thead><tr><th>Syscall</th><th>Number</th><th>Description</th><th>C Signature</th></tr></thead>\n      <tbody>\n        <tr><td>read</td><td>0</td><td>Read bytes from file descriptor into buffer</td><td style=\"color:var(--t2);font-size:11px\">ssize_t read(int fd, void *buf, size_t count)</td></tr>\n        <tr><td>write</td><td>1</td><td>Write bytes from buffer to file descriptor</td><td style=\"color:var(--t2);font-size:11px\">ssize_t write(int fd, const void *buf, size_t count)</td></tr>\n        <tr><td>open</td><td>2</td><td>Open a file, return file descriptor</td><td style=\"color:var(--t2);font-size:11px\">int open(const char *path, int flags, mode_t mode)</td></tr>\n        <tr><td>fork</td><td>57</td><td>Duplicate current process (copy-on-write)</td><td style=\"color:var(--t2);font-size:11px\">pid_t fork(void)</td></tr>\n        <tr><td>execve</td><td>59</td><td>Replace process image with new program</td><td style=\"color:var(--t2);font-size:11px\">int execve(const char *path, char *argv[], char *envp[])</td></tr>\n        <tr><td>mmap</td><td>9</td><td>Map file or memory into process address space</td><td style=\"color:var(--t2);font-size:11px\">void *mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off)</td></tr>\n        <tr><td>clone</td><td>56</td><td>Create thread (shared address space)</td><td style=\"color:var(--t2);font-size:11px\">int clone(int (*fn)(void*), void *stack, int flags, void *arg)</td></tr>\n        <tr><td>kill</td><td>62</td><td>Send signal to a process</td><td style=\"color:var(--t2);font-size:11px\">int kill(pid_t pid, int sig)</td></tr>\n        <tr><td>ioctl</td><td>16</td><td>Device-specific control operations</td><td style=\"color:var(--t2);font-size:11px\">int ioctl(int fd, unsigned long request, ...)</td></tr>\n        <tr><td>exit</td><td>60</td><td>Terminate the calling process</td><td style=\"color:var(--t2);font-size:11px\">void exit(int status)</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"term\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div>\n        <div class=\"td\" style=\"background:#febc2e\"></div>\n        <div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">strace — trace system calls of a running process</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── TRACE SYSCALLS OF A PROCESS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">strace -e trace=open,read,write curl https://example.com 2>&1 | head -14</span></span>\n        <span class=\"ocn\">openat(AT_FDCWD, \"/etc/ssl/certs/ca-certificates.crt\", O_RDONLY) = 3</span>\n        <span class=\"out\">read(3, \"-----BEGIN CERTIFICATE-----\\n...\", 4096) = 4096</span>\n        <span class=\"ocn\">openat(AT_FDCWD, \"/etc/resolv.conf\", O_RDONLY|O_CLOEXEC) = 4</span>\n        <span class=\"out\">read(4, \"nameserver 8.8.8.8\\n\", 4096) = 19</span>\n        <span class=\"oyn\">write(1, \"&lt;!doctype html&gt;...\", 1256) = 1256</span>\n        <span class=\"sec\">──── COUNT SYSCALLS SUMMARY ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">strace -c ls / 2>&1 | tail -8</span></span>\n        <span class=\"out\">% time     seconds  usecs/call     calls    syscall</span>\n        <span class=\"out\">──────── ──────────────────────────────────────────</span>\n        <span class=\"oyn\"> 64.21    0.000301          12        24  getdents64</span>\n        <span class=\"oyn\"> 14.89    0.000070           5        12  openat</span>\n        <span class=\"ocn\">  9.40    0.000044           3        13  fstat</span>\n        <span class=\"ogn\">  5.11    0.000024           2         8  mmap</span>\n        <span class=\"sec\">──── SYSCALL EXECUTION PATH ────</span>\n        <span class=\"out\">User: write(1, \"hello\\n\", 6)</span>\n        <span class=\"out\">  → CPU executes 'syscall' instruction → Ring 3 → Ring 0</span>\n        <span class=\"out\">  → kernel/sys_ni.c: dispatch table entry [1] → ksys_write()</span>\n        <span class=\"out\">  → vfs_write() → file_operations.write() → returns to user</span>\n        <span class=\"out\">  → Ring 0 → Ring 3 (rax = bytes written or -errno)</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 03 — PROCESS MANAGEMENT ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">⚡</span><span class=\"pt\">Process Management — Lifecycle, States &amp; Signals</span><span class=\"pn\">PANEL 03</span></div>\n  <div class=\"pb\">\n\n    <!-- Process states -->\n    <div style=\"margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">Process State Machine</div>\n      <div style=\"display:flex;flex-wrap:wrap;gap:10px;margin-bottom:12px;align-items:center\">\n        <span class=\"proc-state ps-run\">R — Running</span>\n        <span style=\"color:var(--t3)\">→</span>\n        <span class=\"proc-state ps-wait\">D — Uninterruptible Sleep</span>\n        <span style=\"color:var(--t3)\">→</span>\n        <span class=\"proc-state ps-sleep\">S — Interruptible Sleep</span>\n        <span style=\"color:var(--t3)\">→</span>\n        <span class=\"proc-state ps-zombie\">Z — Zombie</span>\n        <span style=\"color:var(--t3)\">→</span>\n        <span class=\"proc-state ps-stop\">T — Stopped</span>\n      </div>\n      <div class=\"info\"><span class=\"ic\">ℹ</span><span><span class=\"hl\">D state (uninterruptible)</span> = process waiting for I/O that cannot be interrupted — e.g., NFS hang, disk I/O. High D-state process count = I/O bottleneck or storage issue. Cannot be killed with SIGKILL while in D state.</span></div>\n    </div>\n\n    <!-- process tree visual -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">Live Process Hierarchy</div>\n    <div class=\"ptree\">\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:4px\">\n        <span class=\"proc-state ps-run\" style=\"font-size:9px\">R</span>\n        <span style=\"color:var(--y);font-family:var(--sans);font-weight:700;font-size:13px\">systemd [1]</span>\n        <span style=\"color:var(--t3);font-size:11px\">— PID 1, all processes are descendants</span>\n      </div>\n      <div style=\"padding-left:20px;border-left:1px solid var(--b2);margin-left:6px\">\n        <div style=\"color:var(--t3);margin:-2px 0\">│</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:var(--t3)\">├──</span><span class=\"proc-state ps-sleep\" style=\"font-size:9px\">S</span><span style=\"color:var(--c)\">sshd [1102]</span><span style=\"color:var(--t3);font-size:11px\">— SSH daemon, listens :22</span></div>\n        <div style=\"padding-left:28px\"><div style=\"display:flex;align-items:center;gap:8px;margin-top:2px\"><span style=\"color:var(--t3)\">└──</span><span class=\"proc-state ps-run\" style=\"font-size:9px\">R</span><span style=\"color:var(--g)\">sshd [2341] → bash [2342] → ps [3891]</span><span style=\"color:var(--t3);font-size:11px\">— your session</span></div></div>\n        <div style=\"color:var(--t3);margin:2px 0\">│</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:var(--t3)\">├──</span><span class=\"proc-state ps-sleep\" style=\"font-size:9px\">S</span><span style=\"color:var(--c)\">nginx [1500]</span><span style=\"color:var(--t3);font-size:11px\">— web server master process</span></div>\n        <div style=\"padding-left:28px\">\n          <div style=\"display:flex;align-items:center;gap:8px;margin-top:2px\"><span style=\"color:var(--t3)\">├──</span><span class=\"proc-state ps-sleep\" style=\"font-size:9px\">S</span><span style=\"color:var(--t2)\">nginx worker [1501]</span></div>\n          <div style=\"display:flex;align-items:center;gap:8px;margin-top:2px\"><span style=\"color:var(--t3)\">└──</span><span class=\"proc-state ps-sleep\" style=\"font-size:9px\">S</span><span style=\"color:var(--t2)\">nginx worker [1502]</span></div>\n        </div>\n        <div style=\"color:var(--t3);margin:2px 0\">│</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:var(--t3)\">├──</span><span class=\"proc-state ps-sleep\" style=\"font-size:9px\">S</span><span style=\"color:var(--c)\">dockerd [1890]</span><span style=\"color:var(--t3);font-size:11px\">— Docker daemon</span></div>\n        <div style=\"color:var(--t3);margin:2px 0\">│</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:var(--t3)\">└──</span><span class=\"proc-state ps-zombie\" style=\"font-size:9px\">Z</span><span style=\"color:var(--r)\">defunct [3200]</span><span style=\"color:var(--t3);font-size:11px\">— zombie: exited but parent hasn't called wait()</span></div>\n      </div>\n    </div>\n\n    <!-- Signals table -->\n    <div style=\"margin-top:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">Critical Signals</div>\n      <table class=\"stbl\">\n        <thead><tr><th>Signal</th><th>Number</th><th>Default Action</th><th>Use Case</th></tr></thead>\n        <tbody>\n          <tr><td>SIGHUP</td><td>1</td><td style=\"color:var(--y)\">Terminate / Reload</td><td style=\"color:var(--t2)\">Reload config without restart (nginx, sshd)</td></tr>\n          <tr><td>SIGINT</td><td>2</td><td style=\"color:var(--y)\">Terminate</td><td style=\"color:var(--t2)\">Ctrl+C from terminal</td></tr>\n          <tr><td>SIGKILL</td><td>9</td><td style=\"color:var(--r)\">Terminate (uncatchable)</td><td style=\"color:var(--t2)\">Force kill — cannot be ignored or handled</td></tr>\n          <tr><td>SIGSEGV</td><td>11</td><td style=\"color:var(--r)\">Core dump</td><td style=\"color:var(--t2)\">Segmentation fault — invalid memory access</td></tr>\n          <tr><td>SIGTERM</td><td>15</td><td style=\"color:var(--y)\">Terminate (catchable)</td><td style=\"color:var(--t2)\">Graceful shutdown — allows cleanup</td></tr>\n          <tr><td>SIGSTOP</td><td>19</td><td style=\"color:var(--p)\">Stop (uncatchable)</td><td style=\"color:var(--t2)\">Pause process — Ctrl+Z</td></tr>\n          <tr><td>SIGCHLD</td><td>17</td><td style=\"color:var(--g)\">Ignore</td><td style=\"color:var(--t2)\">Child process changed state — reap zombies</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- Terminal -->\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Process management commands</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── FORK + EXEC (PROCESS CREATION) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">bash -c 'echo \"Parent PID: $$\"; sleep 5 &amp; echo \"Child PID: $!\"'</span></span>\n        <span class=\"out\">Parent PID: 4210</span>\n        <span class=\"ogn\">Child PID: 4211</span>\n        <span class=\"sec\">──── PROCESS SNAPSHOT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">ps aux --sort=-%cpu | head -6</span></span>\n        <span class=\"out\">USER       PID  %CPU %MEM  VSZ    RSS  STAT COMMAND</span>\n        <span class=\"ocn\">root      1234  12.3  2.1  876432  85420  Ssl  /usr/bin/python3 app.py</span>\n        <span class=\"out\">www-data  1500   3.1  0.4  325604  16920  S    nginx: worker</span>\n        <span class=\"out\">root      1890   1.2  1.8  1242880 74096  Ssl  /usr/bin/dockerd</span>\n        <span class=\"sec\">──── ZOMBIE PROCESS DETECTION ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">ps aux | grep -w Z</span></span>\n        <span class=\"orn\">root      3200   0.0  0.0      0     0  Z    [myapp] &lt;defunct&gt;</span>\n        <span class=\"sec\">──── SEND SIGNALS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">kill -SIGHUP 1500     # reload nginx config</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">kill -9 3200         # force kill zombie's parent</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">kill -SIGSTOP 1234   # pause python process</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 04 — CFS SCHEDULER ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">📊</span><span class=\"pt\">CFS Scheduler — Completely Fair Scheduling</span><span class=\"pn\">PANEL 04</span></div>\n  <div class=\"pb\">\n    <div class=\"grid2\">\n      <div class=\"cb y\">\n        <div class=\"cbt\">How CFS Works</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          CFS uses a <span class=\"hy\">red-black tree</span> (ordered by <code>vruntime</code>) to track all runnable processes. The process with the <span class=\"hl\">smallest vruntime</span> runs next — guaranteeing fairness over time.<br><br>\n          <code>vruntime</code> increases while a process runs, weighted by <span class=\"hc\">nice value</span> (priority). Low-priority tasks accumulate vruntime faster → get less CPU time.\n        </div>\n      </div>\n      <div class=\"cb\">\n        <div class=\"cbt\">Scheduling Classes (Priority Order)</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.9\">\n          <span style=\"color:var(--r)\">1. SCHED_DEADLINE</span> — real-time, CBS algorithm<br>\n          <span style=\"color:var(--o)\">2. SCHED_FIFO</span> — real-time FIFO, runs until yields<br>\n          <span style=\"color:var(--y)\">3. SCHED_RR</span> — real-time round-robin with timeslice<br>\n          <span style=\"color:var(--g)\">4. SCHED_NORMAL (CFS)</span> — standard processes<br>\n          <span style=\"color:var(--t3)\">5. SCHED_IDLE</span> — runs only when CPU is idle\n        </div>\n      </div>\n    </div>\n\n    <!-- Scheduler visualisation -->\n    <div style=\"margin-top:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">CPU Timeslice Allocation (4-core system, 100ms window)</div>\n      <div class=\"sched-track\">\n        <div class=\"sched-row\">\n          <div class=\"sched-label\">CPU 0</div>\n          <div class=\"sched-bar-wrap\">\n            <div class=\"sched-slot\" style=\"width:35%;background:rgba(0,255,136,.2);color:var(--g)\">nginx [35%]</div>\n            <div class=\"sched-slot\" style=\"width:20%;background:rgba(0,212,255,.18);color:var(--c)\">sshd [20%]</div>\n            <div class=\"sched-slot\" style=\"width:30%;background:rgba(255,215,0,.18);color:var(--y)\">python [30%]</div>\n            <div class=\"sched-slot\" style=\"width:15%;background:rgba(255,255,255,.06);color:var(--t3)\">idle</div>\n          </div>\n        </div>\n        <div class=\"sched-row\">\n          <div class=\"sched-label\">CPU 1</div>\n          <div class=\"sched-bar-wrap\">\n            <div class=\"sched-slot\" style=\"width:50%;background:rgba(157,78,221,.2);color:var(--p)\">dockerd [50%]</div>\n            <div class=\"sched-slot\" style=\"width:25%;background:rgba(255,140,0,.18);color:var(--o)\">mysqld [25%]</div>\n            <div class=\"sched-slot\" style=\"width:25%;background:rgba(255,255,255,.06);color:var(--t3)\">idle</div>\n          </div>\n        </div>\n        <div class=\"sched-row\">\n          <div class=\"sched-label\">CPU 2</div>\n          <div class=\"sched-bar-wrap\">\n            <div class=\"sched-slot\" style=\"width:80%;background:rgba(255,59,59,.18);color:var(--r)\">compile [80%]</div>\n            <div class=\"sched-slot\" style=\"width:20%;background:rgba(255,255,255,.06);color:var(--t3)\">idle</div>\n          </div>\n        </div>\n        <div class=\"sched-row\" style=\"margin-bottom:0\">\n          <div class=\"sched-label\">CPU 3</div>\n          <div class=\"sched-bar-wrap\">\n            <div class=\"sched-slot\" style=\"width:100%;background:rgba(255,255,255,.04);color:var(--t3)\">idle — load balancer may migrate tasks</div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Scheduler inspection</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── VIEW SCHEDULING POLICY OF A PROCESS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">chrt -p 1234</span></span>\n        <span class=\"out\">pid 1234's current scheduling policy: SCHED_OTHER</span>\n        <span class=\"out\">pid 1234's current scheduling priority: 0</span>\n        <span class=\"sec\">──── SET REAL-TIME PRIORITY ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">chrt -f -p 50 1234   # SCHED_FIFO priority 50</span></span>\n        <span class=\"sec\">──── NICE VALUE (USER-SPACE PRIORITY) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">nice -n 19 tar czf backup.tar.gz /data  # lowest priority</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">renice -n -5 -p 1234                    # raise existing proc priority</span></span>\n        <span class=\"sec\">──── CGROUPS CPU QUOTA ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemctl set-property nginx.service CPUQuota=25%</span></span>\n        <span class=\"ocn\"># nginx now cannot use more than 25% of total CPU</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 05 — MEMORY MANAGEMENT ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">◫</span><span class=\"pt\">Memory Management — Virtual Memory &amp; Address Space</span><span class=\"pn\">PANEL 05</span></div>\n  <div class=\"pb\">\n    <div class=\"grid2\" style=\"margin-bottom:14px\">\n      <div class=\"cb\">\n        <div class=\"cbt\">Virtual Memory — Why It Exists</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          Every process believes it has the <span class=\"hl\">entire address space</span> (0x0000 → 0xFFFF…) to itself. The kernel + MMU (Memory Management Unit) transparently map virtual pages → physical page frames.<br><br>\n          This enables: <span class=\"hc\">process isolation</span> (each has own space), <span class=\"hc\">swap</span> (page to disk when RAM full), <span class=\"hc\">memory-mapped files</span> (mmap), and <span class=\"hc\">ASLR</span> (randomise base addresses).\n        </div>\n      </div>\n      <div class=\"cb g\">\n        <div class=\"cbt\">Page Fault Handling</div>\n        <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n          When a process accesses a virtual address with <span class=\"hl\">no physical mapping</span>, the CPU raises a <strong>page fault</strong> interrupt.<br><br>\n          Kernel decides: is this a <span class=\"hc\">valid access</span> (page just not loaded)? → allocate physical frame, update page table, resume. Or an <span class=\"hr\">invalid access</span> (SIGSEGV)? → kill the process.\n        </div>\n      </div>\n    </div>\n\n    <!-- Process virtual address space map -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">x86-64 Process Virtual Address Space Layout</div>\n    <div class=\"mem-map\">\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\">0xFFFF…FFFF</div>\n        <div class=\"mem-seg ms-kernel\">\n          <div class=\"mem-seg-name\" style=\"color:var(--y)\">Kernel Space (Ring 0)</div>\n          <div class=\"mem-seg-desc\">kernel code, data, page tables — user cannot access — mapped in every process</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\" style=\"font-size:9px\">↑ grows down</div>\n        <div class=\"mem-seg ms-stack\">\n          <div class=\"mem-seg-name\" style=\"color:var(--o)\">Stack</div>\n          <div class=\"mem-seg-desc\">local variables, function call frames, return addresses — grows toward lower addresses</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\"></div>\n        <div class=\"mem-seg ms-gap\">\n          <div class=\"mem-seg-name\" style=\"color:var(--t3);font-size:11px\">unmapped (guard region + ASLR randomisation)</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\" style=\"font-size:9px\">↑ grows up</div>\n        <div class=\"mem-seg ms-heap\">\n          <div class=\"mem-seg-name\" style=\"color:var(--c)\">Heap</div>\n          <div class=\"mem-seg-desc\">dynamic allocations (malloc/new) — grows upward — managed by brk()/mmap()</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\"></div>\n        <div class=\"mem-seg ms-data\">\n          <div class=\"mem-seg-name\" style=\"color:var(--p)\">BSS + Data Segment</div>\n          <div class=\"mem-seg-desc\">uninitialised globals (BSS), initialised globals and static variables (data)</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\">low address</div>\n        <div class=\"mem-seg ms-text\">\n          <div class=\"mem-seg-name\" style=\"color:var(--g)\">Text Segment (Code)</div>\n          <div class=\"mem-seg-desc\">executable instructions — read-only, shared between processes running same binary</div>\n        </div>\n      </div>\n      <div class=\"mem-row\">\n        <div class=\"mem-addr\">0x0000…0000</div>\n        <div class=\"mem-seg ms-null\">\n          <div class=\"mem-seg-name\" style=\"color:var(--r)\">NULL page (unmapped)</div>\n          <div class=\"mem-seg-desc\">accessing address 0 = SIGSEGV — null pointer dereference protection</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Memory inspection tools</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── VIEW PROCESS MEMORY MAP ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">cat /proc/1234/maps | head -10</span></span>\n        <span class=\"ocn\">55a4b2e00000-55a4b2e3b000 r--p 00000000 08:01 263744  /usr/bin/python3</span>\n        <span class=\"ogn\">55a4b4027000-55a4b4075000 rw-p 00000000 00:00 0       [heap]</span>\n        <span class=\"orn\">7ffd8e200000-7ffd8e221000 rw-p 00000000 00:00 0       [stack]</span>\n        <span class=\"ocn\">ffffffffff600000-ffffffffff601000 --xp                [vsyscall]</span>\n        <span class=\"sec\">──── MEMORY USAGE OVERVIEW ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">free -h</span></span>\n        <span class=\"out\">              total   used   free  shared  buff/cache  available</span>\n        <span class=\"out\">Mem:           15Gi   4.2Gi  8.1Gi  512Mi     2.9Gi      10.2Gi</span>\n        <span class=\"out\">Swap:           4Gi   124Mi  3.9Gi</span>\n        <span class=\"sec\">──── PAGE FAULT STATS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">ps -o pid,comm,minflt,majflt -p 1234</span></span>\n        <span class=\"out\">  PID COMMAND     MINFLT  MAJFLT</span>\n        <span class=\"ocn\"> 1234 python3      48291      12   ← majflt=disk reads (slow)</span>\n        <span class=\"sec\">──── OOM KILLER LOG ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">dmesg | grep -i \"killed process\"</span></span>\n        <span class=\"orn\">[14521.44] Out of memory: Killed process 3841 (java) total-vm:2097152kB</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 06 — VFS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">📂</span><span class=\"pt\">VFS — Virtual File System Layer</span><span class=\"pn\">PANEL 06</span></div>\n  <div class=\"pb\">\n    <div class=\"cb g\" style=\"margin-bottom:14px\">\n      <div class=\"cbt\">What is VFS?</div>\n      <div style=\"color:var(--t);font-size:12.5px;line-height:1.7\">\n        VFS is an <span class=\"hl\">abstraction layer</span> inside the kernel that presents a uniform file API (<code>open</code>, <code>read</code>, <code>write</code>, <code>stat</code>) regardless of the underlying storage format. Whether you read from ext4, XFS, tmpfs, NFS, procfs, sysfs, or even a character device — you always call the same syscalls. VFS dispatches internally to the correct filesystem driver.\n      </div>\n    </div>\n\n    <!-- VFS call chain -->\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:16px;margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">VFS Call Chain — open(\"/etc/passwd\")</div>\n      <div style=\"display:flex;flex-direction:column;gap:0;max-width:600px\">\n        <div style=\"display:flex;gap:12px;align-items:center\">\n          <div style=\"width:200px;min-width:200px;background:rgba(41,121,255,.1);border:1px solid rgba(41,121,255,.3);padding:8px 12px;text-align:center\">\n            <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:#5599ff\">User Process</div>\n            <div style=\"font-size:10px;color:var(--t3)\">glibc open(\"/etc/passwd\", O_RDONLY)</div>\n          </div>\n        </div>\n        <div style=\"padding-left:100px;color:var(--t3);font-size:12px;padding:4px 0 4px 100px\">↓ syscall (openat #257)</div>\n        <div style=\"display:flex;gap:12px;align-items:center\">\n          <div style=\"width:200px;min-width:200px;background:rgba(0,255,136,.08);border:1px solid rgba(0,255,136,.3);padding:8px 12px;text-align:center\">\n            <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--g)\">VFS Layer</div>\n            <div style=\"font-size:10px;color:var(--t3)\">do_sys_openat2() → vfs_open()</div>\n          </div>\n          <div style=\"font-size:11px;color:var(--t3)\">path resolution, dentry cache lookup, inode lookup</div>\n        </div>\n        <div style=\"padding-left:100px;color:var(--t3);font-size:12px;padding:4px 0 4px 100px\">↓ file_operations dispatch</div>\n        <div style=\"display:flex;gap:12px;align-items:center\">\n          <div style=\"width:200px;min-width:200px;background:rgba(255,215,0,.08);border:1px solid rgba(255,215,0,.3);padding:8px 12px;text-align:center\">\n            <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--y)\">ext4 Driver</div>\n            <div style=\"font-size:10px;color:var(--t3)\">ext4_file_open() → reads inode from disk</div>\n          </div>\n          <div style=\"font-size:11px;color:var(--t3)\">fetches block group, inode table entry for /etc/passwd</div>\n        </div>\n        <div style=\"padding-left:100px;color:var(--t3);font-size:12px;padding:4px 0 4px 100px\">↓ block layer → disk I/O</div>\n        <div style=\"display:flex;gap:12px;align-items:center\">\n          <div style=\"width:200px;min-width:200px;background:rgba(255,140,0,.08);border:1px solid rgba(255,140,0,.3);padding:8px 12px;text-align:center\">\n            <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--o)\">Block Device</div>\n            <div style=\"font-size:10px;color:var(--t3)\">NVMe driver → physical read → page cache</div>\n          </div>\n        </div>\n        <div style=\"padding-left:100px;color:var(--t3);font-size:12px;padding:4px 0 4px 100px\">↓ returns fd to user</div>\n        <div style=\"display:flex;gap:12px;align-items:center\">\n          <div style=\"width:200px;min-width:200px;background:rgba(0,212,255,.07);border:1px solid rgba(0,212,255,.3);padding:8px 12px;text-align:center\">\n            <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--c)\">File Descriptor</div>\n            <div style=\"font-size:10px;color:var(--t3)\">fd=3 returned to process — index into fd table</div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">VFS exploration</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── MOUNTED FILESYSTEMS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">cat /proc/mounts | column -t | head -12</span></span>\n        <span class=\"ocn\">sysfs      /sys           sysfs    rw,nosuid,nodev,noexec  0 0</span>\n        <span class=\"ocn\">proc       /proc          proc     rw,nosuid,nodev,noexec  0 0</span>\n        <span class=\"oyn\">devtmpfs   /dev           devtmpfs rw,nosuid               0 0</span>\n        <span class=\"ogn\">/dev/nvme0n1p2  /      ext4     rw,relatime             0 0</span>\n        <span class=\"out\">tmpfs      /run           tmpfs    rw,nosuid,nodev         0 0</span>\n        <span class=\"sec\">──── INODE INFO ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">stat /etc/passwd</span></span>\n        <span class=\"out\">  File: /etc/passwd</span>\n        <span class=\"ocn\">  Size: 1872     Blocks: 8    IO Block: 4096   regular file</span>\n        <span class=\"out\">Device: 8,2  Inode: 924673  Links: 1</span>\n        <span class=\"oyn\">Access: (0644/-rw-r--r--)  Uid: (0/root)  Gid: (0/root)</span>\n        <span class=\"sec\">──── OPEN FILES PER PROCESS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">lsof -p 1234 | head -8</span></span>\n        <span class=\"out\">COMMAND  PID  USER   FD  TYPE  DEVICE SIZE/OFF  NODE  NAME</span>\n        <span class=\"ocn\">python3 1234  root  cwd   DIR   8,2   4096    262147  /opt/app</span>\n        <span class=\"out\">python3 1234  root    0u  CHR   136,0  0t0         3  /dev/pts/0</span>\n        <span class=\"out\">python3 1234  root    3r  REG   8,2   1872   924673  /etc/passwd</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 07 — IPC ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">⇄</span><span class=\"pt\">IPC — Inter-Process Communication</span><span class=\"pn\">PANEL 07</span></div>\n  <div class=\"pb\">\n    <div class=\"grid3\">\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">▶</div>\n        <div class=\"ipc-name\">Pipes (Anonymous)</div>\n        <div class=\"ipc-desc\">Unidirectional byte stream between parent and child. Created by pipe() syscall. No filesystem path.</div>\n        <div class=\"ipc-cmd\">ls | grep .conf | wc -l</div>\n      </div>\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">⇌</div>\n        <div class=\"ipc-name\">Named Pipes (FIFO)</div>\n        <div class=\"ipc-desc\">Pipe with a filesystem path. Unrelated processes can communicate. Persists until deleted.</div>\n        <div class=\"ipc-cmd\">mkfifo /tmp/mypipe</div>\n      </div>\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">⚡</div>\n        <div class=\"ipc-name\">Signals</div>\n        <div class=\"ipc-desc\">Async notification to a process. Limited data (signal number only). Used for control (stop, kill, reload).</div>\n        <div class=\"ipc-cmd\">kill -SIGUSR1 &lt;pid&gt;</div>\n      </div>\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">📬</div>\n        <div class=\"ipc-name\">Message Queues</div>\n        <div class=\"ipc-desc\">Kernel-managed message buffer. Typed messages, persistent until removed. POSIX mq or System V.</div>\n        <div class=\"ipc-cmd\">mq_open(\"/myqueue\", ...)</div>\n      </div>\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">◫</div>\n        <div class=\"ipc-name\">Shared Memory</div>\n        <div class=\"ipc-desc\">Fastest IPC — maps same physical pages into multiple process address spaces. Requires explicit synchronization.</div>\n        <div class=\"ipc-cmd\">shm_open() / mmap()</div>\n      </div>\n      <div class=\"ipc-card\">\n        <div class=\"ipc-icon\">🔌</div>\n        <div class=\"ipc-name\">Unix Domain Sockets</div>\n        <div class=\"ipc-desc\">Socket API over a filesystem path. Full-duplex. Used by Docker, systemd, Xorg, DBus, PostgreSQL locally.</div>\n        <div class=\"ipc-cmd\">/var/run/docker.sock</div>\n      </div>\n    </div>\n\n    <div class=\"warn\" style=\"margin-top:12px\">\n      <span class=\"wc\">⚠</span>\n      <span><strong style=\"color:var(--y)\">Security note:</strong> Unix domain sockets inherit filesystem permissions. <code>/var/run/docker.sock</code> writable by a user = root-equivalent container escape. Always audit socket permissions: <code>ls -la /var/run/*.sock</code></span>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 08 — BOOT PROCESS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">🔄</span><span class=\"pt\">Linux Boot Process — BIOS → GRUB → Kernel → systemd</span><span class=\"pn\">PANEL 08</span></div>\n  <div class=\"pb\">\n    <div style=\"display:flex;flex-direction:column\">\n      <div class=\"boot-step\">\n        <div class=\"boot-line\"></div>\n        <div class=\"boot-dot\">1</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">BIOS / UEFI — Power-On Self Test</div>\n          <div class=\"boot-desc\">CPU starts at reset vector (0xFFFFFFF0). BIOS/UEFI runs POST: checks RAM, detects hardware, enumerates PCIe devices. UEFI reads GPT partition table and finds EFI System Partition (ESP).</div>\n          <div class=\"boot-cmd\">EFI: /boot/efi/EFI/ubuntu/grubx64.efi → hands control to GRUB</div>\n        </div>\n      </div>\n      <div class=\"boot-step\">\n        <div class=\"boot-line\"></div>\n        <div class=\"boot-dot\">2</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">GRUB2 — GRand Unified Bootloader</div>\n          <div class=\"boot-desc\">GRUB reads <code>/boot/grub/grub.cfg</code>, displays boot menu. Loads compressed kernel image (<code>vmlinuz</code>) and initial RAM disk (<code>initramfs</code>) into memory. Passes kernel parameters.</div>\n          <div class=\"boot-cmd\">linux /boot/vmlinuz-6.8.0 root=/dev/nvme0n1p2 ro quiet splash</div>\n        </div>\n      </div>\n      <div class=\"boot-step\">\n        <div class=\"boot-line\"></div>\n        <div class=\"boot-dot\">3</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">Kernel Decompression + Early Init</div>\n          <div class=\"boot-desc\">Kernel decompresses itself. Sets up memory management, CPU features (CPUID), GDT/IDT, enables paging. Mounts initramfs (tmpfs) as temporary root. Loads essential drivers from initramfs modules.</div>\n          <div class=\"boot-cmd\">dmesg | head -20  → see early kernel messages</div>\n        </div>\n      </div>\n      <div class=\"boot-step\">\n        <div class=\"boot-line\"></div>\n        <div class=\"boot-dot\">4</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">initramfs → Real Root Mount</div>\n          <div class=\"boot-desc\">initramfs runs <code>/init</code> script: loads disk drivers (NVMe, LVM, mdraid), decrypts LUKS if needed, mounts real root filesystem (<code>/dev/nvme0n1p2</code>), pivots root (<code>switch_root</code>).</div>\n          <div class=\"boot-cmd\">lsinitramfs /boot/initrd.img-6.8.0 | head -20</div>\n        </div>\n      </div>\n      <div class=\"boot-step\">\n        <div class=\"boot-line\"></div>\n        <div class=\"boot-dot\">5</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">PID 1 — systemd starts</div>\n          <div class=\"boot-desc\">Kernel executes <code>/sbin/init</code> → symlink → <code>systemd</code> as PID 1. systemd reads unit files. Activates default target (<code>multi-user.target</code> or <code>graphical.target</code>) by resolving dependencies.</div>\n          <div class=\"boot-cmd\">systemctl get-default  →  graphical.target</div>\n        </div>\n      </div>\n      <div class=\"boot-step\">\n        <div class=\"boot-dot\">6</div>\n        <div class=\"boot-body\">\n          <div class=\"boot-title\">systemd Targets — Service Activation</div>\n          <div class=\"boot-desc\">systemd activates units in parallel: mounts filesystems, starts network, launches daemons (sshd, nginx, cron, docker). Login prompt appears. Total boot time measured by <code>systemd-analyze</code>.</div>\n          <div class=\"boot-cmd\">systemd-analyze blame | head -10  → slowest services</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Boot analysis &amp; systemd</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── BOOT TIMING ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemd-analyze</span></span>\n        <span class=\"out\">Startup finished in 1.423s (firmware) + 2.891s (loader) + 1.204s (kernel)</span>\n        <span class=\"ogn\">                 + 4.312s (userspace) = 9.831s graphical.target</span>\n        <span class=\"sec\">──── SLOWEST SERVICES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemd-analyze blame | head -6</span></span>\n        <span class=\"orn\">  4.201s apt-daily-upgrade.service</span>\n        <span class=\"out\">  1.840s snapd.service</span>\n        <span class=\"out\">  1.330s NetworkManager-wait-online.service</span>\n        <span class=\"sec\">──── BOOT DEPENDENCY TREE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemctl list-dependencies multi-user.target | head -10</span></span>\n        <span class=\"ocn\">multi-user.target</span>\n        <span class=\"out\">● ├─cron.service</span>\n        <span class=\"out\">● ├─dbus.service</span>\n        <span class=\"out\">● ├─networking.service</span>\n        <span class=\"out\">● └─ssh.service</span>\n        <span class=\"sec\">──── KERNEL BOOT MESSAGES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">dmesg | grep -E \"Freeing|Mounted|NET|EXT4\" | head -8</span></span>\n        <span class=\"ocn\">[    0.000000] Freeing SMP alternatives memory: 44K</span>\n        <span class=\"ocn\">[    1.822103] EXT4-fs (nvme0n1p2): mounted filesystem</span>\n        <span class=\"ocn\">[    2.101344] NET: Registered PF_INET6 protocol family</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 09 — SYSTEMD ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">⚙</span><span class=\"pt\">systemd — Modern Init System &amp; Service Manager</span><span class=\"pn\">PANEL 09</span></div>\n  <div class=\"pb\">\n    <div class=\"grid2\" style=\"margin-bottom:14px\">\n      <div class=\"cb g\">\n        <div class=\"cbt\">systemd Unit Types</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.9\">\n          <span class=\"hl\">.service</span> — daemon processes (nginx.service, sshd.service)<br>\n          <span class=\"hl\">.socket</span> — socket activation (starts service on connection)<br>\n          <span class=\"hl\">.timer</span> — scheduled tasks (replaces cron)<br>\n          <span class=\"hl\">.mount</span> — filesystem mount points<br>\n          <span class=\"hl\">.target</span> — group of units (like runlevels)<br>\n          <span class=\"hl\">.path</span> — triggers on filesystem path change<br>\n          <span class=\"hl\">.slice</span> — cgroup resource boundary\n        </div>\n      </div>\n      <div class=\"cb y\">\n        <div class=\"cbt\">Targets ↔ SysV Runlevels</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.9\">\n          <span class=\"hy\">poweroff.target</span> → runlevel 0 (halt)<br>\n          <span class=\"hy\">rescue.target</span> → runlevel 1 (single user)<br>\n          <span class=\"hy\">multi-user.target</span> → runlevel 3 (no GUI)<br>\n          <span class=\"hy\">graphical.target</span> → runlevel 5 (with GUI)<br>\n          <span class=\"hy\">reboot.target</span> → runlevel 6 (reboot)<br>\n          <span class=\"hy\">emergency.target</span> → minimal shell, root only\n        </div>\n      </div>\n    </div>\n\n    <!-- sample unit file -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">Sample systemd Service Unit File</div>\n    <div class=\"term\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">/etc/systemd/system/myapp.service</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"oyn\">[Unit]</span>\n        <span class=\"out\">Description=My Python Web Application</span>\n        <span class=\"out\">After=network.target postgresql.service</span>\n        <span class=\"out\">Requires=postgresql.service</span>\n        <span class=\"oyn\" style=\"margin-top:6px;display:block\">[Service]</span>\n        <span class=\"out\">Type=notify</span>\n        <span class=\"out\">User=myapp</span>\n        <span class=\"out\">WorkingDirectory=/opt/myapp</span>\n        <span class=\"out\">ExecStart=/opt/myapp/venv/bin/gunicorn app:app -b 0.0.0.0:8000</span>\n        <span class=\"out\">ExecReload=/bin/kill -HUP $MAINPID</span>\n        <span class=\"ogn\">Restart=on-failure          # auto-restart if crashed</span>\n        <span class=\"ogn\">RestartSec=5s</span>\n        <span class=\"out\">StandardOutput=journal      # logs go to journald</span>\n        <span class=\"out\">StandardError=journal</span>\n        <span class=\"ocn\">PrivateTmp=true             # isolated /tmp</span>\n        <span class=\"ocn\">NoNewPrivileges=true        # cannot gain new privs</span>\n        <span class=\"ocn\">ProtectSystem=strict        # read-only system dirs</span>\n        <span class=\"ocn\">CapabilityBoundingSet=CAP_NET_BIND_SERVICE</span>\n        <span class=\"oyn\" style=\"margin-top:6px;display:block\">[Install]</span>\n        <span class=\"out\">WantedBy=multi-user.target</span>\n        <span class=\"sec\">──── MANAGE THE SERVICE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemctl daemon-reload</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemctl enable --now myapp.service</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">systemctl status myapp.service</span></span>\n        <span class=\"ogn\">● myapp.service - My Python Web Application</span>\n        <span class=\"out\">     Loaded: loaded (/etc/systemd/system/myapp.service; enabled)</span>\n        <span class=\"ogn\">     Active: active (running) since Sun 2026-05-03 10:14:22 UTC; 2h 14m ago</span>\n        <span class=\"out\">   Main PID: 4821 (gunicorn)</span>\n        <span class=\"out\">     CGroup: /system.slice/myapp.service</span>\n        <span class=\"out\">             ├─4821 gunicorn master</span>\n        <span class=\"out\">             ├─4822 gunicorn worker[0]</span>\n        <span class=\"out\">             └─4823 gunicorn worker[1]</span>\n        <span class=\"sec\">──── VIEW LOGS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">journalctl -u myapp.service -f --since \"1 hour ago\"</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 10 — SECURITY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">🔒</span><span class=\"pt\">Security Perspective — Kernel Attack Surface</span><span class=\"pn\">PANEL 10</span></div>\n  <div class=\"pb\">\n    <div class=\"grid2\">\n      <div class=\"cb r\">\n        <div class=\"cbt\">Red Team — Kernel &amp; Process Attacks</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>Kernel exploits: dirty COW, ptrace abuse, eBPF escapes</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>Race conditions in syscall handlers → privilege escalation</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>SUID/SGID binaries → run as root without sudo</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>IPC socket abuse → /var/run/docker.sock escape</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>Memory corruption: heap spray, buffer overflow in kernel modules</li>\n          <li style=\"padding:4px 0;display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span>systemd unit misconfiguration → persistent backdoor</li>\n        </ul>\n      </div>\n      <div class=\"cb g\">\n        <div class=\"cbt\">Blue Team — Kernel Hardening</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>sysctl hardening: ASLR=2, dmesg_restrict=1, kptr_restrict=2</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>seccomp profiles: whitelist only needed syscalls (Docker default)</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>Capabilities: drop all, grant only required (CAP_NET_BIND_SERVICE)</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>systemd service sandboxing: PrivateTmp, NoNewPrivileges, ProtectSystem</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>LSM: SELinux or AppArmor mandatory access control policies</li>\n          <li style=\"padding:4px 0;display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span>Kernel patches: apply CVE patches, lockdown mode (Secure Boot)</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"term\" style=\"margin-top:12px\">\n      <div class=\"tbar\">\n        <div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Kernel hardening audit commands</span>\n      </div>\n      <div class=\"tbody\">\n        <span class=\"sec\">──── SYSCTL SECURITY SETTINGS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">sysctl -a | grep -E \"aslr|dmesg|kptr|ptrace\" 2>/dev/null</span></span>\n        <span class=\"ogn\">kernel.randomize_va_space = 2    # ASLR full (2=best)</span>\n        <span class=\"orn\">kernel.dmesg_restrict = 0        # BAD: anyone can read dmesg</span>\n        <span class=\"orn\">kernel.kptr_restrict = 0         # BAD: kernel pointers exposed</span>\n        <span class=\"orn\">kernel.yama.ptrace_scope = 0     # BAD: any proc can ptrace any proc</span>\n        <span class=\"sec\">──── HARDENING FIX ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">cat >> /etc/sysctl.d/99-hardening.conf << EOF</span></span>\n        <span class=\"ocn\">kernel.dmesg_restrict = 1</span>\n        <span class=\"ocn\">kernel.kptr_restrict = 2</span>\n        <span class=\"ocn\">kernel.yama.ptrace_scope = 1</span>\n        <span class=\"ocn\">kernel.unprivileged_bpf_disabled = 1</span>\n        <span class=\"out\">EOF</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">sysctl --system</span></span>\n        <span class=\"sec\">──── FIND SUID BINARIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span class=\"cmd\">find / -perm -4000 -type f 2>/dev/null</span></span>\n        <span class=\"out\">/usr/bin/sudo</span><span class=\"out\">/usr/bin/passwd</span>\n        <span class=\"orn\">/tmp/rootkit_suid    ← unknown SUID binary — investigate!</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 11 — CHECKLIST ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">✔</span><span class=\"pt\">Auditor / Security Checklist — Step 2 Verification</span><span class=\"pn\">PANEL 11</span></div>\n  <div class=\"pb\">\n    <ul class=\"cl\">\n      <li><div class=\"chk\">✓</div>Can you explain what a system call is and trace syscalls with strace?<span class=\"tag tc\">SYSCALL</span></li>\n      <li><div class=\"chk\">✓</div>Can you explain all 5 process states (R, D, S, Z, T) and what causes each?<span class=\"tag ty\">PROCESS</span></li>\n      <li><div class=\"chk\">✓</div>Do you understand the 7 process address space segments and what lives in each?<span class=\"tag tp\">MEMORY</span></li>\n      <li><div class=\"chk\">✓</div>Can you explain how the CFS scheduler allocates CPU time using vruntime?<span class=\"tag tg\">SCHED</span></li>\n      <li><div class=\"chk\">✓</div>Do you understand what VFS is and why it exists (uniform file API over multiple FS types)?<span class=\"tag tc\">VFS</span></li>\n      <li><div class=\"chk\">✓</div>Can you list 6 IPC mechanisms and explain the security implication of Unix sockets?<span class=\"tag to\">IPC</span></li>\n      <li><div class=\"chk\">✓</div>Can you trace the boot sequence from UEFI → GRUB → kernel → initramfs → systemd?<span class=\"tag tg\">BOOT</span></li>\n      <li><div class=\"chk\">✓</div>Can you write a hardened systemd service unit with PrivateTmp, NoNewPrivileges, ProtectSystem?<span class=\"tag ty\">SYSTEMD</span></li>\n      <li><div class=\"chk\">✓</div>Can you identify insecure sysctl values (dmesg_restrict=0, kptr_restrict=0) and fix them?<span class=\"tag tp\">HARDEN</span></li>\n      <li><div class=\"chk\">✓</div>Can you find all SUID binaries on a system and assess which are anomalous?<span class=\"tag to\">AUDIT</span></li>\n    </ul>\n  </div>\n</div>\n\n<!-- ═══ PANEL 12 — SUMMARY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span class=\"pi\">◉</span><span class=\"pt\">Summary — Step 2 Complete</span><span class=\"pn\">PANEL 12</span></div>\n  <div class=\"pb\">\n    <div class=\"grid3\" style=\"margin-bottom:14px\">\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Kernel Architecture</div>\n        <div class=\"sc-v\">Monolithic design: all subsystems in Ring 0 as one binary. LKMs extend without reboot. CPU rings enforce the user/kernel boundary. Syscalls are the only crossing point.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Process + Memory</div>\n        <div class=\"sc-v\">CFS scheduler gives each process fair CPU via vruntime red-black tree. Virtual memory isolates processes, enables swap and ASLR. Page faults trigger kernel frame allocation.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Boot + systemd</div>\n        <div class=\"sc-v\">UEFI → GRUB → vmlinuz → initramfs → PID 1 (systemd). systemd resolves unit dependencies, activates targets in parallel. Service sandboxing is built into unit files.</div>\n      </div>\n    </div>\n    <div class=\"next\">\n      <div>\n        <div class=\"ns-t\">▶ Next: Step 3 — Linux File System Architecture</div>\n        <div class=\"ns-s\">FHS hierarchy · inodes · hard/soft links · permissions · chmod · ACLs · LVM · mounting · ext4 internals</div>\n      </div>\n      <button class=\"ns-b\" onclick=\"window.sendPrompt && window.sendPrompt('Start Step 3')\">$ Start Step 3 →</button>\n    </div>\n  </div>\n</div>\n\n</div>";

export default function LinuxStep2() {
  return <LessonDocument title="Architecture Deep Dive" styles={styles} markup={markup} />;
}
